// Tool body for `agents__send`, run in Core's Deno sandbox.
//
// This file is a FRAGMENT, not an ES module: Core splices it into an async IIFE
// (`build_inline_tool_program` in crates/core/tool-exec/src/lib.rs) with `input`
// (the call arguments), `caller` (the DISPATCHING agent, host-derived) and `host`
// (the capability bridge) already bound, and the body `return`s the tool result.
// A top-level `return` is therefore correct here and `export` is not. The
// manifest's `runnables[].config.code` is sealed from this file — edit here, then
// reseal (see plugin.test.mjs, which fails on drift).
//
// `send` is the ASYNCHRONOUS half of the mailbox: it drops a message in another
// agent's inbox and returns immediately. The recipient reads it at the start of
// its next turn, injected by the `agent-comms.deliver` hook. Nothing wakes an
// idle agent — that is the documented v1 limit, and `agents__ask` is the path
// for an answer you need now.

const MAX_TEXT = 4000;
const MAX_INBOX = 20;
const MAX_THREAD = 12;
// Hop 1 is a user-initiated message. Hop 2 is the one relay it may cause. A
// third would be an agent chain nobody asked for, and every hop is a real agent
// run on the user's budget — so the chain stops here, deterministically, rather
// than relying on the models involved to lose interest.
const MAX_HOPS = 2;

/** Read a JSON value from plugin KV, or `fallback` when absent/corrupt. */
async function readJson(key, fallback) {
	const raw = await host.storage.get(key);
	if (raw === null || raw === undefined || raw === "") {
		return fallback;
	}
	try {
		const parsed = JSON.parse(String(raw));
		return parsed === null ? fallback : parsed;
	} catch (_e) {
		// A half-written value must not brick the mailbox: treat it as empty.
		return fallback;
	}
}

/** Read a small non-negative integer from plugin KV; 0 when absent/unparseable. */
async function readInt(key) {
	const raw = await host.storage.get(key);
	const n = Number.parseInt(String(raw ?? "0"), 10);
	return Number.isFinite(n) && n > 0 ? n : 0;
}

// Message ids come from a stored counter, not a clock: the sandbox denies
// `Date.now()` (and a tool that reads one is not replayable), so the sequence IS
// the ordering. It is monotonic across every message this node relays.
async function nextSeq() {
	const next = (await readInt("seq")) + 1;
	await host.storage.set("seq", String(next));
	return next;
}

/** The canonical, order-independent key for a pair's message history. */
function threadKey(a, b) {
	return a < b ? `thread:${a}|${b}` : `thread:${b}|${a}`;
}

const to = String(input.to ?? "").trim();
if (to === "") {
	throw new Error(
		"agents__send: 'to' is required — the id of the agent to message. Call agents__directory to see the agents on this node."
	);
}
const text = String(input.text ?? "").trim();
if (text === "") {
	throw new Error("agents__send: 'text' is required (the message to send)");
}

// WHO IS SENDING IS NOT THE MODEL'S TO SAY. `caller.agent_id` is resolved by
// Core's dispatch, so an agent cannot post as another one by naming it in its
// arguments. `input.from` is honoured only for the agent-less callers (a
// workflow or a monitor step), which have no identity to derive.
const from =
	String(caller.agent_id ?? "").trim() || String(input.from ?? "").trim();
if (from === "") {
	throw new Error(
		"agents__send: the calling agent could not be identified, and no 'from' was supplied"
	);
}
if (from === to) {
	throw new Error(
		`agents__send: '${to}' is the calling agent — a message to yourself is a note, not a message`
	);
}

// How deep this agent already is in a relayed chain: from the conversation it is
// answering in (set by the delivery hook) or, when it is itself running as a
// delegated sub-agent with no conversation, from its agent-scoped marker.
const arrivedByConversation = caller.conversation_id
	? await readInt(`hops.conv:${caller.conversation_id}`)
	: 0;
const arrivedByAgent = await readInt(`hops.agent:${from}`);
const hops = Math.max(arrivedByConversation, arrivedByAgent) + 1;
if (hops > MAX_HOPS) {
	return {
		ok: false,
		refused: "hop_limit",
		hops: hops,
		max_hops: MAX_HOPS,
		error: `agents__send: this message would be hop ${hops} of an agent-to-agent chain and the limit is ${MAX_HOPS}. Answer the user directly instead of relaying further.`,
	};
}

const seq = await nextSeq();
const id = `m${seq}`;
const message = {
	id: id,
	seq: seq,
	from: from,
	from_conversation: caller.conversation_id ?? null,
	to: to,
	text: text.slice(0, MAX_TEXT),
	hops: hops,
	reply_to: input.reply_to ? String(input.reply_to) : null,
};

// The inbox is per-AGENT, not per-conversation: a message addressed to an agent
// is delivered in whichever of its conversations runs next. Capped, oldest
// dropped — an undelivered backlog is not worth an unbounded KV value.
const inboxKey = `inbox:${to}`;
const inbox = await readJson(inboxKey, []);
const nextInbox = (Array.isArray(inbox) ? inbox : []).concat([message]);
await host.storage.set(
	inboxKey,
	JSON.stringify(nextInbox.slice(-MAX_INBOX))
);

// The pair's history, so a later `agents__ask` can carry context and
// `agents__thread` can show what was said.
const tKey = threadKey(from, to);
const thread = await readJson(tKey, []);
const nextThread = (Array.isArray(thread) ? thread : []).concat([
	{ seq: seq, from: from, to: to, text: message.text },
]);
await host.storage.set(tKey, JSON.stringify(nextThread.slice(-MAX_THREAD)));

return {
	ok: true,
	id: id,
	from: from,
	to: to,
	hops: hops,
	queued: nextInbox.slice(-MAX_INBOX).length,
	delivery:
		"queued — it is injected at the start of the recipient's next turn. Nothing wakes an idle agent; use agents__ask when you need the answer now.",
};

// Tool body for `agents__ask`, run in Core's Deno sandbox.
//
// This file is a FRAGMENT, not an ES module: Core splices it into an async IIFE
// (`build_inline_tool_program` in crates/core/tool-exec/src/lib.rs) with `input`,
// `caller` (the DISPATCHING agent, host-derived) and `host` bound, and the body
// `return`s the tool result. The manifest's `runnables[].config.code` is sealed
// from this file — edit here, then reseal (plugin.test.mjs fails on drift).
//
// `ask` is the SYNCHRONOUS half of the mailbox: the addressed agent runs now, in
// a clean context, and its answer comes back as this tool's result. It is
// `host.runAgent` — the delegation engine — addressed by agent id, with the pair's
// own message history carried in, which is the difference between "delegate a
// subtask" and "ask a colleague who remembers the last thing you asked".

const MAX_TEXT = 4000;
const MAX_THREAD = 12;
const MAX_HISTORY_CHARS = 2000;
const HISTORY_TURNS = 6;
const MAX_HOPS = 2;
// A `busy` marker is only meaningful while the run that wrote it is in flight.
// If a process dies mid-ask the marker survives, and there are two ways out —
// both needed, because the first is instant and the second is the backstop:
//
//   1. OWNERSHIP. A marker records who wrote it. An agent that meets its OWN
//      marker is meeting the wreckage of its own dead ask (a turn runs its tool
//      calls one at a time, so it cannot legitimately be blocked on itself), and
//      clears it. That covers the common case with no waiting at all.
//   2. AGE. A marker written by a DIFFERENT agent expires by distance in the
//      attempt counter, which every ask — including a refused one — advances. So
//      even a foreign stale marker ages out instead of wedging the pair forever.
const BUSY_STALE_AFTER = 25;

async function readJson(key, fallback) {
	const raw = await host.storage.get(key);
	if (raw === null || raw === undefined || raw === "") {
		return fallback;
	}
	try {
		const parsed = JSON.parse(String(raw));
		return parsed === null ? fallback : parsed;
	} catch (_e) {
		return fallback;
	}
}

async function readInt(key) {
	const raw = await host.storage.get(key);
	const n = Number.parseInt(String(raw ?? "0"), 10);
	return Number.isFinite(n) && n > 0 ? n : 0;
}

async function nextSeq() {
	const next = (await readInt("seq")) + 1;
	await host.storage.set("seq", String(next));
	return next;
}

function threadKey(a, b) {
	return a < b ? `thread:${a}|${b}` : `thread:${b}|${a}`;
}

const to = String(input.to ?? "").trim();
if (to === "") {
	throw new Error(
		"agents__ask: 'to' is required — the id of the agent to ask. Call agents__directory to see the agents on this node."
	);
}
const question = String(input.question ?? "").trim();
if (question === "") {
	throw new Error("agents__ask: 'question' is required");
}
const from =
	String(caller.agent_id ?? "").trim() || String(input.from ?? "").trim();
if (from === "") {
	throw new Error(
		"agents__ask: the calling agent could not be identified, and no 'from' was supplied"
	);
}
if (from === to) {
	throw new Error(
		`agents__ask: '${to}' is the calling agent — asking yourself is just thinking, do it directly`
	);
}

const arrivedByConversation = caller.conversation_id
	? await readInt(`hops.conv:${caller.conversation_id}`)
	: 0;
const arrivedByAgent = await readInt(`hops.agent:${from}`);
const hops = Math.max(arrivedByConversation, arrivedByAgent) + 1;
if (hops > MAX_HOPS) {
	return {
		ok: false,
		refused: "hop_limit",
		hops: hops,
		max_hops: MAX_HOPS,
		error: `agents__ask: this would be hop ${hops} of an agent-to-agent chain and the limit is ${MAX_HOPS}. Answer with what you have instead of asking another agent.`,
	};
}

// CYCLE GUARD. `ask` blocks on a real agent run, so A→B→A is not slow, it is a
// deadlocked pair burning two model budgets. Both ends are marked busy for the
// duration: the target (it is running) and the asker (it is waiting), so the
// nested call back up the chain is refused instead of started. The hop limit
// bounds depth; this bounds the *shape*.
//
// The counter is advanced FIRST, before the check can refuse: a refusal that
// returned early would leave the sequence where it was, so a retry would compare
// identical numbers forever and a stale marker could never age out.
const askSeq = await nextSeq();

/** The `{seq, by}` marker at `key`, or null when absent or unreadable. */
async function readBusy(key) {
	const raw = await host.storage.get(key);
	if (raw === null || raw === undefined || raw === "") {
		return null;
	}
	try {
		const parsed = JSON.parse(String(raw));
		return parsed && typeof parsed === "object" ? parsed : null;
	} catch (_e) {
		return null;
	}
}

const busyTarget = await readBusy(`busy:${to}`);
if (
	busyTarget !== null &&
	busyTarget.by !== from &&
	askSeq - Number(busyTarget.seq ?? 0) < BUSY_STALE_AFTER
) {
	return {
		ok: false,
		refused: "cycle",
		error: `agents__ask: '${to}' is already handling a request higher up this same chain. Use agents__send to leave it a message instead of waiting on it.`,
	};
}

const tKey = threadKey(from, to);
const thread = await readJson(tKey, []);
const history = (Array.isArray(thread) ? thread : []).slice(-HISTORY_TURNS);
let historyText = "";
if (history.length > 0) {
	const lines = history.map((m) => `${m.from} → ${m.to}: ${m.text}`);
	historyText = `\n\nWhat the two of you have said before (oldest first):\n${lines
		.join("\n")
		.slice(-MAX_HISTORY_CHARS)}`;
}

// The peer runs with a CLEAN context — it cannot see the asker's conversation —
// so everything it needs is in this task text. That is the same isolation
// `delegate__fanout` gives a subtask, and the reason the pair history above is
// carried in explicitly rather than assumed.
const task = [
	`You are the agent "${to}". Another agent on this node, "${from}", is asking you something directly — this is agent-to-agent, not a user turn.`,
	`Answer as yourself, using your own tools and knowledge. Reply with the answer only: no preamble, no restating the question.`,
	`If you cannot answer, say so plainly and say what you would need.`,
	historyText,
	`\n\nQuestion from ${from}:\n${question.slice(0, MAX_TEXT)}`,
].join("\n");

// Claim only what is not already claimed, and release only what was claimed
// HERE. A nested ask (B→C inside A→B) must not delete the marker A is relying
// on: whoever wrote a marker is the only one who may remove it.
const claimed = [];
async function claim(key) {
	const existing = await readBusy(key);
	if (existing !== null && existing.by !== from) {
		return;
	}
	await host.storage.set(key, JSON.stringify({ seq: askSeq, by: from }));
	claimed.push(key);
}
await claim(`busy:${to}`);
await claim(`busy:${from}`);
// The peer runs as a delegated agent with no conversation of its own, so its own
// hop depth has to travel on an agent-scoped key — otherwise a tool it calls
// mid-answer would read a depth of zero and the chain would be unbounded.
await host.storage.set(`hops.agent:${to}`, String(hops));

let reply = null;
let failure = null;
try {
	const out = await host.runAgent({
		task: task,
		agent_id: to,
		wall_time_secs: input.wall_time_secs,
	});
	reply = typeof out === "string" ? out : JSON.stringify(out);
} catch (e) {
	failure = String((e && e.message) || e);
} finally {
	for (const key of claimed) {
		await host.storage.delete(key);
	}
	await host.storage.delete(`hops.agent:${to}`);
}

if (failure !== null) {
	return {
		ok: false,
		from: from,
		to: to,
		error: `agents__ask: '${to}' did not answer: ${failure}`,
	};
}

// Both halves land in the pair's history, so the next ask carries this exchange
// and `agents__thread` shows a conversation rather than a list of questions.
const answerSeq = await nextSeq();
const nextThread = (Array.isArray(thread) ? thread : []).concat([
	{ seq: askSeq, from: from, to: to, text: question.slice(0, MAX_TEXT) },
	{
		seq: answerSeq,
		from: to,
		to: from,
		text: String(reply ?? "").slice(0, MAX_TEXT),
	},
]);
await host.storage.set(tKey, JSON.stringify(nextThread.slice(-MAX_THREAD)));

return {
	ok: true,
	from: from,
	to: to,
	hops: hops,
	question: question.slice(0, MAX_TEXT),
	reply: String(reply ?? ""),
};

// Tool body for `agents__thread`, run in Core's Deno sandbox.
//
// This file is a FRAGMENT, not an ES module: Core splices it into an async IIFE
// (`build_inline_tool_program` in crates/core/tool-exec/src/lib.rs) with `input`,
// `caller` and `host` bound, and the body `return`s the tool result. The
// manifest's `runnables[].config.code` is sealed from this file — edit here, then
// reseal (plugin.test.mjs fails on drift).
//
// Reading is scoped to the CALLING agent's own threads, and that is the whole
// security posture of this tool: `caller.agent_id` is host-derived, so a `with`
// the model writes can only ever name the OTHER end of one of its own
// conversations. There is deliberately no "read agent X's mailbox" argument.

const MAX_MESSAGES = 12;

async function readJson(key, fallback) {
	const raw = await host.storage.get(key);
	if (raw === null || raw === undefined || raw === "") {
		return fallback;
	}
	try {
		const parsed = JSON.parse(String(raw));
		return parsed === null ? fallback : parsed;
	} catch (_e) {
		return fallback;
	}
}

function threadKey(a, b) {
	return a < b ? `thread:${a}|${b}` : `thread:${b}|${a}`;
}

const me =
	String(caller.agent_id ?? "").trim() || String(input.from ?? "").trim();
if (me === "") {
	throw new Error(
		"agents__thread: the calling agent could not be identified, and no 'from' was supplied"
	);
}

const peer = String(input.with ?? "").trim();

// No peer named → which agents has this one talked to at all. Derived from the
// key set, so it lists real history rather than the node's whole roster (that is
// what agents__directory is for).
if (peer === "") {
	const keys = await host.storage.keys();
	const peers = [];
	for (const key of Array.isArray(keys) ? keys : []) {
		const k = String(key);
		if (!k.startsWith("thread:")) {
			continue;
		}
		const pair = k.slice("thread:".length).split("|");
		if (pair.length !== 2) {
			continue;
		}
		if (pair[0] === me && !peers.includes(pair[1])) {
			peers.push(pair[1]);
		} else if (pair[1] === me && !peers.includes(pair[0])) {
			peers.push(pair[0]);
		}
	}
	return {
		ok: true,
		agent: me,
		peers: peers,
		hint:
			peers.length === 0
				? "No agent-to-agent history yet. agents__directory lists who is on this node."
				: "Call agents__thread again with `with: \"<agent id>\"` to read one of these.",
	};
}

const messages = await readJson(threadKey(me, peer), []);
const rows = (Array.isArray(messages) ? messages : []).slice(-MAX_MESSAGES);

return {
	ok: true,
	agent: me,
	with: peer,
	messages: rows.map((m) => ({
		seq: m.seq ?? null,
		from: m.from ?? null,
		to: m.to ?? null,
		text: String(m.text ?? ""),
	})),
	count: rows.length,
};
